class VelocityTracker {
    private int[] sprintVelocities;
    private int sprintCount = 0;

    public VelocityTracker() {
        sprintVelocities = new int[4];
    }

    public void addSprintVelocity(int velocity) {
        if (sprintCount < sprintVelocities.length) {
            sprintVelocities[sprintCount] = velocity;
            sprintCount++;
        }
    }

    public double getAverageVelocity() {
        if (sprintCount == 0) return 0;
        int sum = 0;
        for (int i = 0; i < sprintCount; i++) {
            sum += sprintVelocities[i];
        }
        return sum / sprintCount;
    }
}

public class Main {
    public static void main(String[] args) {
        VelocityTracker tracker = new VelocityTracker();
        tracker.addSprintVelocity(20);
        tracker.addSprintVelocity(25);
        tracker.addSprintVelocity(15);
        System.out.println(tracker.getAverageVelocity());
    }
}

